const referenceMonth=value=>{const text=String(value||'').toLocaleLowerCase('pt-BR');const months=['janeiro','fevereiro','março','abril','maio','junho','julho','agosto','setembro','outubro','novembro','dezembro'];const year=text.match(/\b(20\d{2})\b/);if(!year)return 0;const named=months.findIndex(month=>text.includes(month));const numeric=text.match(/\b(0?[1-9]|1[0-2])\s*[/-]\s*20\d{2}\b/);const iso=text.match(/\b20\d{2}[-/]\s*(0?[1-9]|1[0-2])\b/);const month=named>=0?named+1:numeric?Number(numeric[1]):iso?Number(iso[1]):0;return Number(year[1])*12+month;};
export const latestFipeCandidate=candidates=>(candidates||[]).reduce((best,item)=>{if(!best)return item;const current=referenceMonth(item.reference),previous=referenceMonth(best.reference);return current>previous||current===previous&&item.principal&&!best.principal?item:best;},null);
