 let active=true,rows=[],selected=null,photoIndex=0,zoom=false,message='',busy='',actionId='',actionPosition={left:0,top:0};const filters={region:'',team:'',from:'',to:'',model:'',status:'',store:'',seller:'',plate:''};const manager=me.role!=='Vendedor';
