 root.querySelector('#used-client-form').addEventListener('input',e=>{const ownerKey=e.target.dataset.ownerField;if(ownerKey){draft.ownerDetails??={};e.target.value=['cpf','cep','phone'].includes(ownerKey)?formatInput(e.target.value,ownerKey):e.target.value;draft.ownerDetails[ownerKey]=e.target.value;return}const key=e.target.dataset.clientField;if(!key)return;draft.clientDetails??={};e.target.value=['cpf','cep','phone'].includes(key)?formatInput(e.target.value,key):e.target.value;draft.clientDetails[key]=e.target.value});
