 function updateConsultationOverview(){
  const total=entries.reduce((sum,[key])=>sum+Number(rowFor(key).amount||0),0);
  const completed=entries.filter(([key])=>consultationComplete(rowFor(key),key!=='senatran')).length;
  const pending=entries.filter(([key])=>rowFor(key).state==='NÃO CONSULTADO').length;
  const count=root.querySelector('[data-consultation-count]'),progress=root.querySelector('[data-consultation-progress]');
  if(count)count.textContent=`${completed} de ${entries.length} concluídas`;
  if(progress){progress.value=completed;progress.max=entries.length;progress.setAttribute('aria-label',`${completed} de ${entries.length} consultas concluídas`)}
  for(const node of root.querySelectorAll('[data-consultation-percent]'))node.textContent=`${Math.round(completed/entries.length*100)}%`;
  for(const node of root.querySelectorAll('[data-consultation-total]'))node.textContent=money(total);
  const done=root.querySelector('[data-consultation-done]'),left=root.querySelector('[data-consultation-pending]');if(done)done.textContent=`${completed} de ${entries.length}`;if(left)left.textContent=String(pending);
  for(const row of root.querySelectorAll('.used-query'))row.dataset.state=row.querySelector('select[data-field="state"]')?.value||'NÃO CONSULTADO';
 }
