  const table=panel.querySelector('.used-consultations');table.querySelector('.used-query-head').innerHTML='<span>Consulta</span><span>Situação</span><span>Débito</span><span>Observação</span><span>Documento</span><span>Portal</span>';
  for(const row of table.querySelectorAll('.used-query')){if(row.classList.contains('no-amount')){const empty=root.ownerDocument.createElement('span');empty.className='used-empty-amount';empty.textContent='—';row.querySelector('.used-note').before(empty)}const attachment=row.querySelector('.used-attachment'),fileLink=attachment?.querySelector('a');if(fileLink){const chip=root.ownerDocument.createElement('span');chip.className='used-attached-file';attachment.prepend(chip);chip.append(fileLink,attachment.querySelector('.used-upload'));attachment.classList.add('has-file')}const select=row.querySelector('select[data-field="state"]');for(const option of select.options)option.value=option.textContent;row.dataset.state=select.value;const link=row.querySelector('.used-query-link:not(.unavailable)');if(link)link.insertAdjacentHTML('afterbegin','<span>Consultar</span>');const name=row.querySelector('.used-query-name');name.querySelector('.used-query-check')?.remove()}
  panel.querySelector('.used-total-footer')?.remove();
